import{_ as s,C as n,o as d,c,j as e,a as l,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const f=JSON.parse('{"title":"文言传","description":"专释乾坤两卦的传——从元亨利贞与六爻时位，到坤道承载与敬义立身，读懂以传解经的义理样板。","frontmatter":{"title":"文言传","description":"专释乾坤两卦的传——从元亨利贞与六爻时位，到坤道承载与敬义立身，读懂以传解经的义理样板。","category":"guide","aliases":["文言传","文言","wen yan zhuan"],"source":["《周易·文言传》"]},"headers":[],"relativePath":"yijing/shi-yi/wen-yan-zhuan.md","filePath":"yijing/shi-yi/wen-yan-zhuan.md","lastUpdated":1788516578000}'),u={name:"yijing/shi-yi/wen-yan-zhuan.md"};function p(m,a,g,b,q,x){const t=n("DaoReadingPrelude"),r=n("DaoTextReading"),h=n("DaoKeywordCards");return d(),c("div",null,[a[0]||(a[0]=e("h1",{id:"文言传",tabindex:"-1"},[l("文言传 "),e("a",{class:"header-anchor",href:"#文言传","aria-label":'Permalink to "文言传"'},"​")],-1)),i(t,{title:"在每一个位置上，做合乎其时的事",summary:"《文言传》只解释乾、坤两卦，却把两卦的卦辞和爻辞展开成一套完整的修身与处世之学。乾讲创始、刚健、进德与知退；坤讲承载、柔顺、守正与成全。读它，不是只找吉凶，而是看人在不同位置上如何安顿自己。",points:[{label:"先读乾",text:"从元亨利贞与潜龙、见龙、飞龙，理解能力如何随时位展开。"},{label:"再读坤",text:"从至柔、含章、括囊与黄中，理解承载并不等于软弱或失去原则。"},{label:"合读",text:"乾坤不是两种互相排斥的人格，而是创始与完成、主动与承接的两面。"}],hint:"乾、坤都不是鼓励人永远向前或永远退让。真正的关键是：知道自己所处的时、位、势，并在其中做合乎其时的事。"}),a[1]||(a[1]=o("",12)),i(r,{colophon:"元亨利贞 · 六龙时位 · 大人合天 · 知进知退",tone:"ink",sections:[{id:"qian-01",sentences:[["文言曰：“元者，善之长也；亨者，嘉之会也；利者，义之和也；贞者，事之干也。”"],["君子体仁，足以长人；嘉会，足以合礼；利物，足以和义；贞固，足以干事。君子行此四者，故曰：乾，元亨利贞。"]]},{id:"qian-02",sentences:[["初九曰：“潜龙勿用。”何谓也？子曰：“龙德而隐者也。不易乎世，不成乎名；遁世而无闷，不见是而无闷；乐则行之，忧则违之；确乎其不可拔，乾龙也。”"],["九二曰：“见龙在田，利见大人。”何谓也？子曰：“龙德而正中者也。庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。君德也。”"]]},{id:"qian-03",sentences:[["九三曰：“君子终日乾乾，夕惕若，厉无咎。”何谓也？子曰：“君子进德修业，忠信，所以进德也；修辞立其诚，所以居业也。知至至之，可与几也；知终终之，可与存义也。”"],["是故，居上位而不骄，在下位而不忧。故乾乾，因其时而惕，虽危而无咎矣。"],["九四曰：“或跃在渊，无咎。”何谓也？子曰：“上下无常，非为邪也；进退无恒，非离群也。君子进德修业，欲及时也，故无咎。”"]]},{id:"qian-04",sentences:[["九五曰：“飞龙在天，利见大人。”何谓也？子曰：“同声相应，同气相求；水流湿，火就燥；云从龙，风从虎。圣人作而万物覩，本乎天者亲上，本乎地者亲下，则各从其类也。”"],["上九曰：“亢龙有悔。”何谓也？子曰：“贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。”"]]},{id:"qian-05",sentences:[["乾龙勿用，下也；见龙在田，时舍也；终日乾乾，行事也；或跃在渊，自试也；飞龙在天，上治也；亢龙有悔，穷之灾也；乾元用九，天下治也。"],["乾龙勿用，阳气潜藏；见龙在田，天下文明；终日乾乾，与时偕行；或跃在渊，乾道乃革；飞龙在天，乃位乎天德；亢龙有悔，与时偕极；乾元用九，乃见天则。"]]},{id:"qian-06",sentences:[["乾元者，始而亨者也；利贞者，性情也。乾始能以美利利天下，不言所利。大矣哉！大哉乾乎！刚健中正，纯粹精也。"],["六爻发挥，旁通情也；时乘六龙，以御天也；云行雨施，天下平也。"],["君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。"],["君子学以聚之，问以辩之，宽以居之，仁以行之。见龙在田，利见大人，君德也。"]]},{id:"qian-07",sentences:[["九三，重刚而不中，上不在天，下不在田，故乾乾，因其时而惕，虽危无咎矣。"],["九四，重刚而不中，上不在天，下不在田，中不在人，故或之；或之者，疑之也，故无咎。"],["夫大人者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。先天下而天弗违，后天而奉天时。"],["亢之为言也，知进而不知退，知存而不知亡，知得而不知丧。其唯圣人乎？知进退存亡，而不失其正者，其为圣人乎！"]]}],"aria-label":"乾文言原文"}),a[2]||(a[2]=e("h2",{id:"【原典层】坤文言",tabindex:"-1"},[l("【原典层】坤文言 "),e("a",{class:"header-anchor",href:"#【原典层】坤文言","aria-label":'Permalink to "【原典层】坤文言"'},"​")],-1)),i(r,{colophon:"至柔动刚 · 承天时行 · 敬直义方 · 黄中通理",tone:"ink",sections:[{id:"kun-01",sentences:[["文言曰：“坤至柔，而动也刚；至静，而德方；后得主而有常；含万物而化光。坤其道顺乎？承天而时行。”"],["积善之家，必有馀庆；积不善之家，必有馀殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辨之不早辨也。履霜坚冰至，盖言顺也。"]]},{id:"kun-02",sentences:[["直其正也，方其义也。君子敬以直内，义以方外，敬义立而德不孤。“直，方，大，不习无不利”，则不疑其所行也。"],["阴虽有美，含之；以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成，而代有终也。"]]},{id:"kun-03",sentences:[["天地变化，草木蕃；天地闭，贤人隐。“括囊；无咎，无誉”，盖言谨也。"],["君子黄中通理，正位居体，美在其中，而畅于四支，发于事业，美之至也。"]]},{id:"kun-04",sentences:[["阴疑于阳，必战。为其嫌于无阳也，故称龙焉；犹未离其类也，故称血焉。夫玄黄者，天地之杂也，天玄而地黄。"]]}],"aria-label":"坤文言原文"}),a[3]||(a[3]=e("blockquote",null,[e("p",null,"注：坤文言中的「妻道」「臣道」属于古代社会的象征与秩序语境，现代阅读不直接将其转化为性别或身份规范。「艮为鼻」等后世取象讨论也应与本文乾坤原典分开，不混同于文言传本身。")],-1)),a[4]||(a[4]=e("h2",{id:"【原典层】字词释义",tabindex:"-1"},[l("【原典层】字词释义 "),e("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(h,{items:[{term:"元亨利贞",pinyin:["yuán","hēng","lì","zhēn"],meaning:"文言分别解释为善之长、嘉之会、义之和、事之干。四字不是四个孤立吉兆，而是一条从发端、通达、合宜到守正的成事结构。"},{term:"体仁",pinyin:["tǐ","rén"],meaning:"以仁为体，把仁落实为自身的行动，因此足以长养、成全他人，而不只是口头谈仁。"},{term:"贞固",pinyin:["zhēn","gù"],meaning:"守住原则与根本。「固」不是僵硬地拒绝变化，而是在方法变化时仍不失诚实、责任与分寸。"},{term:"潜龙",pinyin:["qián","lóng"],meaning:"德性与能力尚在隐伏、行动尚未完成的阶段。勿用不是不学习，而是不把未成熟强行推到台前。"},{term:"见龙",pinyin:["xiàn","lóng"],meaning:"德性开始显现并影响周围。其基础是庸言可信、庸行谨慎、善世而不自伐。"},{term:"知几",pinyin:["zhī","jī"],meaning:"知道事情将动未动的微小征兆。知至至之、知终终之，都是对时机和边界的辨认。"},{term:"大人",pinyin:["dà","rén"],meaning:"不是单指地位高的人，而是能与天地、日月、四时相合，先后皆能奉时而行的德性与担当。"},{term:"至柔动刚",pinyin:["zhì","róu","dòng","gāng"],meaning:"坤外在柔顺，实际行动却有承载和完成的力量。柔并不等于弱，静也不等于没有方向。"},{term:"承天时行",pinyin:["chéng","tiān","shí","xíng"],meaning:"承接规律并依时行动，不是盲从天意，而是看清条件、角色和时势后完成自己的工作。"},{term:"含章",pinyin:["hán","zhāng"],meaning:"内有才华、美德和光明，却不急于显露或争功。含不是压抑才能，而是不让自我证明取代事情本身。"},{term:"括囊",pinyin:["kuò","náng"],meaning:"扎紧袋口，象征天地闭塞或时机不宜时的谨慎收敛；不能把它滥用为逃避应尽责任的借口。"},{term:"黄中通理",pinyin:["huáng","zhōng","tōng","lǐ"],meaning:"内守中正而通达事理，正位居体，内在之美最终流布于言行并落实为事业。"}]}),a[5]||(a[5]=o("",39))])}const k=s(u,[["render",p]]);export{f as __pageData,k as default};
